def compute(vars):
    operating_cash = vars["v1"]
    cash_and_equivalents = vars["v2"] * 1000  # Convert billions to millions

    if cash_and_equivalents == 0:
        return None

    result = (operating_cash / cash_and_equivalents) * 100

    return {
        "value": result,
        "trace": {
            "operating_cash": operating_cash,
            "cash_and_equivalents_in_millions": cash_and_equivalents,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
